export const classMoves = pgTable("class_moves", {
	id: uuid().defaultRandom().primaryKey().notNull(),
	recordId: uuid("record_id").notNull(),
	fromClass: text("from_class").notNull(),
	toClass: text("to_class").notNull(),
	requestedBy: uuid("requested_by").notNull(),
	requestedAt: timestamp("requested_at", { withTimezone: true, mode: 'string' }).defaultNow().notNull(),
	via: text().default('person').notNull(),
	status: text().default('pending').notNull(),
	error: text(),
	finishedAt: timestamp("finished_at", { withTimezone: true, mode: 'string' }),
	acceptedRules: text("accepted_rules").array(),
	confirmation: text(),
	acceptedPrint: text("accepted_print"),
	acceptedAud: text("accepted_aud"),
	acceptedSpaceId: uuid("accepted_space_id"),
	acceptedScope: text("accepted_scope"),
	textOnly: boolean("text_only").default(false).notNull(),
}, (table) => [
	check("class_moves_accepted_check", sql`(accepted_rules IS NULL) OR ((from_class = 'closed'::text) AND (to_class = 'open'::text) AND (confirmation IS NOT NULL) AND ((cardinality(accepted_rules) >= 1) AND (cardinality(accepted_rules) <= 64)) AND (NOT ('nda'::text = ANY (accepted_rules))))`),
	check("class_moves_accepted_scope_check", sql`(accepted_scope IS NULL) OR (accepted_scope = ANY (ARRAY['solo'::text, 'shared'::text]))`),
	check("class_moves_accepted_whitelist", sql`(accepted_rules IS NULL) OR (accepted_rules <@ ARRAY['phone'::text, 'email_near_name'::text, 'inn'::text, 'passport'::text, 'snils'::text, 'card'::text, 'amount'::text, 'contract_number'::text, 'phone_intl'::text, 'date_of_birth'::text, 'bank_account'::text, 'national_id'::text])`),
	check("class_moves_check", sql`from_class <> to_class`),
	check("class_moves_confirmation_check", sql`(confirmation IS NULL) OR (confirmation = ANY (ARRAY['human_workplace'::text, 'agent_relayed'::text]))`),
	check("class_moves_consent_check", sql`(confirmation IS DISTINCT FROM 'human_workplace'::text) OR ((accepted_rules IS NULL) AND (NOT text_only)) OR ((accepted_print IS NOT NULL) AND (accepted_aud IS NOT NULL) AND (accepted_space_id IS NOT NULL) AND (accepted_scope IS NOT NULL))`),
	check("class_moves_from_class_check", sql`from_class = ANY (ARRAY['open'::text, 'closed'::text])`),
	check("class_moves_shared_pii_check", sql`(accepted_scope IS DISTINCT FROM 'shared'::text) OR (accepted_rules IS NULL) OR (NOT (accepted_rules && ARRAY['passport'::text, 'snils'::text, 'card'::text, 'bank_account'::text, 'national_id'::text]))`),
	check("class_moves_status_check", sql`status = ANY (ARRAY['pending'::text, 'copying'::text, 'verifying'::text, 'done'::text, 'failed'::text])`),
	check("class_moves_text_only_check", sql`(NOT text_only) OR ((from_class = 'closed'::text) AND (to_class = 'open'::text) AND (confirmation = 'human_workplace'::text) AND (accepted_print IS NOT NULL))`),
	check("class_moves_to_class_check", sql`to_class = ANY (ARRAY['open'::text, 'closed'::text])`),
	foreignKey({
			columns: [table.requestedBy],
			foreignColumns: [people.id],
			name: "class_moves_requested_by_fkey"
		}),
	index("class_moves_pending_idx").using("btree", table.status.asc().nullsLast().op("text_ops")).where(sql`(status = ANY (ARRAY['pending'::text, 'copying'::text, 'verifying'::text]))`),
	index("class_moves_record_requested_idx").using("btree", table.recordId.asc().nullsLast(), table.requestedAt.desc().nullsFirst(), table.id.desc().nullsFirst()),
]);

