export const recordLinks = pgTable("record_links", {
	id: uuid().primaryKey().notNull(),
	srcId: uuid("src_id").notNull(),
	dstId: uuid("dst_id").notNull(),
	srcClass: text("src_class").notNull(),
	dstClass: text("dst_class").notNull(),
	srcKey: uuid("src_key"),
	dstKey: uuid("dst_key"),
	relation: text().notNull(),
	status: text().notNull(),
	method: text().notNull(),
	confidence: real(),
	detailClass: text("detail_class").notNull(),
	processor: jsonb(),
	createdBy: uuid("created_by"),
	createdAt: timestamp("created_at", { withTimezone: true, mode: 'string' }).defaultNow().notNull(),
	updatedAt: timestamp("updated_at", { withTimezone: true, mode: 'string' }).defaultNow().notNull(),
	decidedBy: uuid("decided_by"),
	decidedAt: timestamp("decided_at", { withTimezone: true, mode: 'string' }),
}, (table) => [
	check("record_links_confidence_check", sql`(confidence IS NULL) OR ((confidence >= (0)::double precision) AND (confidence <= (1)::double precision))`),
	check("record_links_decided", sql`(decided_by IS NULL) = (decided_at IS NULL)`),
	check("record_links_detail_class_check", sql`detail_class = ANY (ARRAY['open'::text, 'closed'::text])`),
	check("record_links_detail_strict", sql`(detail_class = 'closed'::text) OR ((src_class = 'open'::text) AND (dst_class = 'open'::text))`),
	check("record_links_dst_class_check", sql`dst_class = ANY (ARRAY['open'::text, 'closed'::text])`),
	check("record_links_method_check", sql`method = ANY (ARRAY['extracted_by_model'::text, 'stated_by_human'::text, 'inferred_by_agent'::text])`),
	check("record_links_model", sql`(method <> 'extracted_by_model'::text) OR (processor IS NOT NULL)`),
	check("record_links_not_self", sql`src_id <> dst_id`),
	check("record_links_relation_check", sql`relation = ANY (ARRAY['same'::text, 'refines'::text, 'replaces'::text, 'contradicts'::text, 'resolves'::text, 'derived_from'::text, 'echo_of'::text, 'corrects'::text])`),
	check("record_links_src_class_check", sql`src_class = ANY (ARRAY['open'::text, 'closed'::text])`),
	check("record_links_status_check", sql`status = ANY (ARRAY['proposed'::text, 'active'::text, 'confirmed'::text, 'rejected'::text, 'orphaned'::text])`),
	check("record_links_verdict", sql`(status <> ALL (ARRAY['confirmed'::text, 'rejected'::text])) OR (decided_by IS NOT NULL)`),
	foreignKey({
			columns: [table.createdBy],
			foreignColumns: [people.id],
			name: "record_links_created_by_fkey"
		}),
	foreignKey({
			columns: [table.decidedBy],
			foreignColumns: [people.id],
			name: "record_links_decided_by_fkey"
		}),
	foreignKey({
			columns: [table.dstId],
			foreignColumns: [recordLocations.recordId],
			name: "record_links_dst_id_fkey"
		}).onDelete("cascade"),
	foreignKey({
			columns: [table.srcId],
			foreignColumns: [recordLocations.recordId],
			name: "record_links_src_id_fkey"
		}).onDelete("cascade"),
	index("record_links_dst_idx").using("btree", table.dstId.asc().nullsLast().op("uuid_ops")),
	index("record_links_keys_idx").using("btree", table.srcKey.asc().nullsLast(), table.dstKey.asc().nullsLast(), table.relation.asc().nullsLast()).where(sql`((src_key IS NOT NULL) AND (dst_key IS NOT NULL))`),
	unique("record_links_pair_key").on(table.srcId, table.dstId, table.relation),
]);

